    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}` },
    json: payload
  }).catch(() => {});
}

/** @param {{ x: number, y: number }[]} pts */
function smoothAreaPath(pts, baselineY) {
  if (pts.length === 0) return "";
