    const r = innerR + (s.revenue / maxVal) * (outerR - innerR);
    const x0 = cx + r * Math.cos(a0);
    const y0 = cy + r * Math.sin(a0);
    const x1 = cx + r * Math.cos(a1);
    const y1 = cy + r * Math.sin(a1);
    const large = sliceAngle > Math.PI ? 1 : 0;
    const ix0 = cx + innerR * Math.cos(a0);
    const iy0 = cy + innerR * Math.sin(a0);
    const ix1 = cx + innerR * Math.cos(a1);
    const iy1 = cy + innerR * Math.sin(a1);
    const d = `M ${ix0} ${iy0} L ${x0} ${y0} A ${r} ${r} 0 ${large} 1 ${x1} ${y1} L ${ix1} ${iy1} A ${innerR} ${innerR} 0 ${large} 0 ${ix0} ${iy0} Z`;
    return h(
      "g",
      { key: `p-${i}` },
      [
        h("title", { key: "t" }, `${s.name}: ${formatGhc(s.revenue)}`),
        h("path", {
          key: "path",
          d,
          fill: BLOOM_PALETTE[i % BLOOM_PALETTE.length],
          fillOpacity: 0.72,
          stroke: "rgba(15,23,42,0.45)",
          strokeWidth: 0.75
        })
      ]
    );
  });

  const hub = h("circle", {
    key: "hub",
    cx,
    cy,
    r: innerR - 4,
    fill: "rgb(2 6 23)",
    stroke: "rgba(56,189,248,0.35)",
    strokeWidth: 1
  });

  const legend = slices.map((s, i) =>
    h("div", { key: `lg-${i}`, className: "flex min-w-0 items-center gap-2 text-[11px] text-slate-600 dark:text-slate-300" }, [
      h("span", {
        key: "sw",
        className: "h-2.5 w-2.5 shrink-0 rotate-45 rounded-sm",
        style: { backgroundColor: BLOOM_PALETTE[i % BLOOM_PALETTE.length] }
      }),
      h("span", { className: "min-w-0 flex-1 truncate", title: s.name }, s.name),
      h("span", { className: "shrink-0 font-mono text-xs font-medium text-slate-800 dark:text-slate-100" }, formatGhc(s.revenue))
    ])
  );

  return h("div", { className: "flex flex-col items-stretch gap-4 sm:flex-row sm:items-center sm:justify-between" }, [
    h(
      "div",
      {
        key: "orbit-wrap",
        className:
          "relative mx-auto flex h-[220px] w-[220px] shrink-0 items-center justify-center rounded-full bg-[conic-gradient(from_200deg,rgba(56,189,248,0.08),transparent,rgba(129,140,248,0.1),transparent)] p-1 ring-1 ring-white/10"
      },
      [
        h(
          "svg",
          {
            key: "rose",
            viewBox: "0 0 220 220",
            className: "h-full w-full -rotate-[8deg]",
            role: "img",
            "aria-label": "Revenue bloom by product"
          },
          [...petals, hub]
        )
      ]
    ),
    h("div", { key: "leg", className: "min-w-0 flex-1 space-y-1.5 sm:max-w-[15rem]" }, legend)
  ]);
}
